const assert=require('node:assert/strict');
const {createRuntime,nextPurchaseOrderNumber,nextPaymentRequestNumber,STORE,SESSION}=require('./access-runtime.js');
const F=require('./access-test-fixtures.js');
class Storage{constructor(seed=F.seed(),session='admin'){this.map=new Map([[STORE,JSON.stringify(seed)],[SESSION,session]]);this.reads=[];this.writes=[]}getItem(k){this.reads.push(k);return this.map.has(k)?this.map.get(k):null}setItem(k,v){this.writes.push(k);this.map.set(k,v)}removeItem(k){this.map.delete(k)}}
const assertions=[],test=(key,fn)=>{fn();assertions.push(key)};
test('fresh-read',()=>{let s=new Storage,r=createRuntime({storage:s});r.renderCurrentRoute();assert.ok(s.reads.includes(STORE));assert.ok(s.reads.includes(SESSION))});
test('open-confirm-commit-user',()=>{let s=new Storage,r=createRuntime({storage:s});r.setRoute('users');let opened=r.dispatchAction({action:'new-user',phase:'open'});assert.equal(opened.ok,true);let token=opened.descriptor.operationToken;let confirmed=r.dispatchAction({action:'confirm-access-review',phase:'execute',operationToken:token});assert.equal(confirmed.draft.confirmedRevision,0);let committed=r.dispatchAction({action:'new-user',phase:'commit',operationToken:token,payload:{name:'Test User',email:'test@example.test',username:'test.user',password:'Demo123!'}});assert.equal(committed.ok,true);assert.equal(JSON.parse(s.getItem(STORE)).users.filter(x=>x.username==='test.user').length,1);assert.equal(r.dispatchAction({action:'new-user',phase:'commit',operationToken:token,payload:{}}).ok,false)});
test('stale-commit-denied',()=>{let s=new Storage,r=createRuntime({storage:s});r.setRoute('users');let opened=r.dispatchAction({action:'edit-user',phase:'open',targetId:'worker',resource:{type:'user',id:'worker'}}),state=JSON.parse(s.getItem(STORE));state.meta.storeRevision++;state.users[1].active=false;s.setItem(STORE,JSON.stringify(state));let result=r.dispatchAction({action:'edit-user',phase:'commit',targetId:'worker',resource:{type:'user',id:'worker'},operationToken:opened.descriptor.operationToken,payload:{}});assert.equal(result.ok,false);assert.equal(JSON.parse(s.getItem(STORE)).users[1].active,false)});
test('shared-session',()=>{let s=new Storage,r1=createRuntime({storage:s}),r2=createRuntime({storage:s});assert.equal(r1.renderCurrentRoute().user.id,'admin');s.setItem(SESSION,'worker');r1.refreshFromStorage();r2.refreshFromStorage();assert.equal(r1.renderCurrentRoute().user.id,'worker');assert.equal(r2.renderCurrentRoute().user.id,'worker')});
test('recovery-invalid-json',()=>{let s=new Storage();s.setItem(STORE,'{bad');let r=createRuntime({storage:s});assert.equal(r.renderCurrentRoute().status,'recovery');assert.equal(s.getItem(SESSION),null)});
test('dispatcher-counter',()=>{let s=new Storage,r=createRuntime({storage:s});r.setRoute('users');r.dispatchAction({action:'new-user',phase:'open'});assert.equal(r.getDispatcherCount(),1)});
test('supplier-website-persistence',()=>{let s=new Storage,r=createRuntime({storage:s});r.setRoute('suppliers');let opened=r.dispatchAction({action:'new-supplier',phase:'open'}),created=r.dispatchAction({action:'new-supplier',phase:'commit',operationToken:opened.descriptor.operationToken,payload:{name:'Proveedor Web',ruc:'20111111111',email:'ventas@proveedor.test',website:'https://proveedor.test',address:'Lima',categories:['Mobiliario']}});assert.equal(created.ok,true);let supplier=JSON.parse(s.getItem(STORE)).suppliers.find(item=>item.ruc==='20111111111');assert.equal(supplier.website,'https://proveedor.test');let editing=r.dispatchAction({action:'edit-supplier',phase:'open',targetId:supplier.id,resource:{type:'supplier',id:supplier.id}}),updated=r.dispatchAction({action:'edit-supplier',phase:'commit',targetId:supplier.id,resource:{type:'supplier',id:supplier.id},operationToken:editing.descriptor.operationToken,payload:{...supplier,website:'www.proveedor.test',categories:['Mobiliario']}});assert.equal(updated.ok,true);assert.equal(JSON.parse(s.getItem(STORE)).suppliers.find(item=>item.id===supplier.id).website,'www.proveedor.test')});
test('purchase-order-tracking-statuses',()=>{let s=new Storage,r=createRuntime({storage:s});r.setRoute('project','p1');let opened=r.dispatchAction({action:'edit-order-tracking',phase:'open',targetId:'o1',resource:{type:'order',id:'o1'}}),updated=r.dispatchAction({action:'edit-order-tracking',phase:'commit',targetId:'o1',resource:{type:'order',id:'o1'},operationToken:opened.descriptor.operationToken,payload:{status:'Out for delivery'}});assert.equal(updated.ok,true);assert.equal(JSON.parse(s.getItem(STORE)).orders.find(item=>item.id==='o1').trackingStatus,'Out for delivery');let invalidOpen=r.dispatchAction({action:'edit-order-tracking',phase:'open',targetId:'o1',resource:{type:'order',id:'o1'}}),invalid=r.dispatchAction({action:'edit-order-tracking',phase:'commit',targetId:'o1',resource:{type:'order',id:'o1'},operationToken:invalidOpen.descriptor.operationToken,payload:{status:'Arrived at client warehouse'}});assert.equal(invalid.ok,false)});
test('shared-team-objective-single-record',()=>{let s=new Storage,r=createRuntime({storage:s});r.setRoute('team');let before=JSON.parse(s.getItem(STORE)).tasks.length,opened=r.dispatchAction({action:'assign-team-objective',phase:'open'}),created=r.dispatchAction({action:'assign-team-objective',phase:'commit',operationToken:opened.descriptor.operationToken,payload:{title:'Objetivo compartido',description:'Una sola meta para todos',assignees:['admin-datnya','worker'],due:'2026-09-30'}});assert.equal(created.ok,true);let stored=JSON.parse(s.getItem(STORE)),matches=stored.tasks.filter(task=>task.title==='Objetivo compartido');assert.equal(stored.tasks.length,before+1);assert.equal(matches.length,1);assert.deepEqual(matches[0].assignees,['admin-datnya','worker']);assert.equal('reference'in matches[0],false);s.setItem(SESSION,'worker');r.refreshFromStorage();let taskId=matches[0].id,statusOpen=r.dispatchAction({action:'task',phase:'open',targetId:taskId,resource:{type:'task',id:taskId}}),completed=r.dispatchAction({action:'task',phase:'commit',targetId:taskId,resource:{type:'task',id:taskId},operationToken:statusOpen.descriptor.operationToken,payload:{status:'Completed'}});assert.equal(completed.ok,true);let task=JSON.parse(s.getItem(STORE)).tasks.find(item=>item.id===taskId);assert.equal(task.status,'Completed');assert.equal(task.progress,100);assert.equal(task.statusUpdatedBy,'Jordan Park')});
test('legacy-objective-clones-are-consolidated',()=>{let seed=F.variant(state=>{state.tasks.push({id:'legacy-a',title:'Meta repetida',description:'Compartida',assignee:'admin-datnya',status:'Pending',progress:0,period:'Weekly',reference:'A',due:'2026-09-30'},{id:'legacy-b',title:'Meta repetida',description:'Compartida',assignee:'worker',status:'Pending',progress:0,period:'Weekly',reference:'A',due:'2026-09-30'})}),s=new Storage(seed),r=createRuntime({storage:s});r.renderCurrentRoute();let matches=JSON.parse(s.getItem(STORE)).tasks.filter(task=>task.title==='Meta repetida');assert.equal(matches.length,1);assert.deepEqual(matches[0].assignees,['admin-datnya','worker']);assert.equal('reference'in matches[0],false)});
test('purchase-order-number-follows-project-and-team',()=>{let seed=F.variant(state=>{state.projects.push({id:'p3',code:'VAAK-103',name:'Proyecto nuevo',legal:'Proyecto nuevo SAC',fiscal:'Lima',warehouse:'Almacén',city:'Lima',country:'Perú',team:[]});state.projectCompanies.push({projectId:'p3',companyId:'co3'})}),s=new Storage(seed),r=createRuntime({storage:s});r.setRoute('project','p3');let ffOpen=r.dispatchAction({action:'new-order',phase:'open'}),ff=r.dispatchAction({action:'new-order',phase:'commit',operationToken:ffOpen.descriptor.operationToken,payload:{projectId:'p3',ocTeam:'FFE',supplier:'Proveedor P1'}});assert.equal(ff.ok,true);assert.equal(JSON.parse(s.getItem(STORE)).orders.at(-1).number,'VAAK-103-0001');let osOpen=r.dispatchAction({action:'new-order',phase:'open'}),os=r.dispatchAction({action:'new-order',phase:'commit',operationToken:osOpen.descriptor.operationToken,payload:{projectId:'p3',ocTeam:'OSE',supplier:'Proveedor P1'}});assert.equal(os.ok,true);assert.equal(JSON.parse(s.getItem(STORE)).orders.at(-1).number,'VAAK-103-8001')});
test('purchase-order-preview-number',()=>{let state=F.seed();assert.equal(nextPurchaseOrderNumber(state,'p1','FFE'),'PRJ-041-0001');assert.equal(nextPurchaseOrderNumber(state,'p1','OSE'),'PRJ-041-8001')});
test('technical-sheet-text-fields-persist',()=>{let s=new Storage,r=createRuntime({storage:s});r.setRoute('project','p1');let opened=r.dispatchAction({action:'new-spec',phase:'open'}),description='Long technical description. '.repeat(300),created=r.dispatchAction({action:'new-spec',phase:'commit',operationToken:opened.descriptor.operationToken,payload:{projectId:'p1',name:'Custom item',code:'SPEC-999',productCode:'VENDOR-ABC-42',size:'120 x 60 x 45 cm',quantity:'12',unit:'EACH',quantityOrdered:'12 EACH',color:'Walnut / Matte lacquer',reference:'RH-7788',description,category:'Mobiliario',cost:'$ 1.00'}});assert.equal(created.ok,true);let spec=JSON.parse(s.getItem(STORE)).specs.at(-1);assert.equal(spec.productCode,'VENDOR-ABC-42');assert.equal(spec.reference,'RH-7788');assert.equal(spec.size,'120 x 60 x 45 cm');assert.equal(spec.color,'Walnut / Matte lacquer');assert.equal(spec.quantityOrdered,'12 EACH');assert.equal(spec.description,description.trim());assert.equal('designFinish'in spec,false);assert.equal('construction'in spec,false);assert.equal('notes'in spec,false)});
test('duplicate-spec-copies-all-data-with-unique-editable-code',()=>{let s=new Storage(undefined,'worker'),r=createRuntime({storage:s});r.setRoute('project','p1');let before=JSON.parse(s.getItem(STORE)),source=before.specs.find(spec=>spec.id==='sp-own'),opened=r.dispatchAction({action:'duplicate-spec',phase:'open',targetId:source.id,resource:{type:'spec',id:source.id}}),foreign=r.dispatchAction({action:'duplicate-spec',phase:'open',targetId:'sp-foreign',resource:{type:'spec',id:'sp-foreign'}});assert.equal(opened.ok,true);assert.equal(foreign.ok,false);assert.equal(opened.descriptor.kind,'confirm-duplicate-spec');assert.notEqual(opened.descriptor.suggestedCode,source.code);let code='SPEC-DUPLICATE-101',created=r.dispatchAction({action:'duplicate-spec',phase:'commit',targetId:source.id,resource:{type:'spec',id:source.id},operationToken:opened.descriptor.operationToken,payload:{code}});assert.equal(created.ok,true);let saved=JSON.parse(s.getItem(STORE)),duplicate=saved.specs.find(spec=>spec.code===code),sourceComparable={...source},duplicateComparable={...duplicate};delete sourceComparable.id;delete sourceComparable.code;delete duplicateComparable.id;delete duplicateComparable.code;assert.deepEqual(duplicateComparable,sourceComparable);assert.notEqual(duplicate.id,source.id);let invalidOpen=r.dispatchAction({action:'duplicate-spec',phase:'open',targetId:source.id,resource:{type:'spec',id:source.id}}),invalid=r.dispatchAction({action:'duplicate-spec',phase:'commit',targetId:source.id,resource:{type:'spec',id:source.id},operationToken:invalidOpen.descriptor.operationToken,payload:{code:source.code}});assert.equal(invalid.ok,false)});
test('purchase-order-conditions-persist',()=>{let s=new Storage,r=createRuntime({storage:s});r.setRoute('project','p1');let conditions=Array.from({length:50},(_,index)=>`Condition ${index+1}`),opened=r.dispatchAction({action:'new-order',phase:'open'}),created=r.dispatchAction({action:'new-order',phase:'commit',operationToken:opened.descriptor.operationToken,payload:{projectId:'p1',ocTeam:'FFE',supplier:'Proveedor P1',conditionsJson:JSON.stringify(conditions)}});assert.equal(created.ok,true);let saved=JSON.parse(s.getItem(STORE)).orders.at(-1);assert.deepEqual(JSON.parse(saved.conditionsJson),conditions)});
test('purchase-order-tax-persists',()=>{let s=new Storage,r=createRuntime({storage:s});r.setRoute('project','p1');let opened=r.dispatchAction({action:'new-order',phase:'open'}),created=r.dispatchAction({action:'new-order',phase:'commit',operationToken:opened.descriptor.operationToken,payload:{projectId:'p1',ocTeam:'FFE',supplier:'Proveedor P1',taxType:'IGV',taxAmount:'180.00',amountCurrency:'S/',amountValue:'1180.00'}});assert.equal(created.ok,true);let saved=JSON.parse(s.getItem(STORE)).orders.at(-1);assert.equal(saved.taxType,'IGV');assert.equal(saved.taxAmount,'180.00');assert.equal(saved.amountValue,'1180.00')});
test('all-persisted-money-fields-round-to-nearest-tenth',()=>{let s=new Storage,r=createRuntime({storage:s});r.setRoute('project','p1');let specOpen=r.dispatchAction({action:'new-spec',phase:'open'}),specResult=r.dispatchAction({action:'new-spec',phase:'commit',operationToken:specOpen.descriptor.operationToken,payload:{projectId:'p1',name:'Rounded spec',code:'ROUND-001',category:'Mobiliario',cost:'$ 345.03'}});assert.equal(specResult.ok,true);assert.equal(JSON.parse(s.getItem(STORE)).specs.at(-1).cost,'$ 345.00');let orderOpen=r.dispatchAction({action:'new-order',phase:'open'}),orderResult=r.dispatchAction({action:'new-order',phase:'commit',operationToken:orderOpen.descriptor.operationToken,payload:{projectId:'p1',ocTeam:'FFE',supplier:'Proveedor P1',items:[{quantity:1,currency:'$',unitCost:345.03},{quantity:1,currency:'$',unitCost:250.57}],taxType:'VAT',taxAmount:'10.04',cifValue:'5.06',amountCurrency:'$',amountValue:'610.67',amount:'$ 610.67'}});assert.equal(orderResult.ok,true);let order=JSON.parse(s.getItem(STORE)).orders.at(-1);assert.deepEqual(order.items.map(item=>item.unitCost),[345,250.6]);assert.equal(order.taxAmount,'10.00');assert.equal(order.cifValue,'5.10');assert.equal(order.amountValue,'610.70');assert.equal(order.amount,'$ 610.70');let invoiceOpen=r.dispatchAction({action:'new-invoice',phase:'open',targetId:'p1',resource:{type:'project',id:'p1'}}),invoiceResult=r.dispatchAction({action:'new-invoice',phase:'commit',targetId:'p1',resource:{type:'project',id:'p1'},operationToken:invoiceOpen.descriptor.operationToken,payload:{totalRequest:'250.57',goods:'345.03',freight:'10.06',packing:'5.04',invoiceTotal:'250.57',paymentAmount:'250.57'}});assert.equal(invoiceResult.ok,true);let invoice=JSON.parse(s.getItem(STORE)).projects.find(project=>project.id==='p1').invoices.at(-1);assert.equal(invoice.totalRequest,'250.60');assert.equal(invoice.goods,'345.00');assert.equal(invoice.freight,'10.10');assert.equal(invoice.packing,'5.00');assert.equal(invoice.invoiceTotal,'250.60');assert.equal(invoice.paymentAmount,'250.60')});
test('payment-request-number-uses-project-code-and-project-sequence',()=>{let state=F.seed();state.projects.find(project=>project.id==='p1').invoices=[{number:'PR-PRJ-041-0003'}];assert.equal(nextPaymentRequestNumber(state,'p1'),'PR-PRJ-041-0004')});
const report={suite:'access-runtime',pass:true,assertions};if(process.argv.includes('--report-json'))console.log(JSON.stringify(report));else console.log('access-runtime: all assertions passed');
